mobile-android-switch--unchecked.snippet:
import { Component } from '@angular/core';
import { AndroidSwitchComponent } from './android-switch.component';

@Component({
  selector: 'app-demo',
  imports: [AndroidSwitchComponent],
  template: `
    <div class="p-4">
        <app-android-switch
            [(checked)]="checked"
            [disabled]="disabled"
            [ariaLabel]="ariaLabel" />
    </div>`,
})
export class DemoComponent {
  checked = false;
  disabled = false;
  ariaLabel = 'Notifications';
  checkedChange(event: unknown) {}
}

